SET XACT_ABORT ON;
SET NOCOUNT ON;
IF DB_NAME() <> 'CodexContractTest' THROW 51000, 'Wrong database.', 1;
BEGIN TRAN;
INSERT dbo.crm_company(company_code,company_name) VALUES ('CODEX_ISOLATED',N'Isolated test company');
DECLARE @company bigint=SCOPE_IDENTITY();
INSERT dbo.crm_user(company_id,login_id,user_name,password_hash) VALUES(@company,'synthetic',N'Synthetic user','unused');
DECLARE @user bigint=SCOPE_IDENTITY();
INSERT dbo.crm_account(company_id,owner_user_id,account_name) VALUES(@company,@user,N'Synthetic account');
DECLARE @account bigint=SCOPE_IDENTITY();
INSERT dbo.crm_opportunity(company_id,account_id,owner_user_id,opportunity_name) VALUES(@company,@account,@user,N'Synthetic opportunity');
DECLARE @opportunity bigint=SCOPE_IDENTITY();
INSERT dbo.crm_contract(company_id,account_id,opportunity_id,owner_user_id,contract_name,contract_amount) VALUES(@company,@account,@opportunity,@user,N'Product A',100);
DECLARE @contract bigint=SCOPE_IDENTITY();
INSERT dbo.crm_contract(company_id,account_id,opportunity_id,owner_user_id,contract_name,contract_amount) VALUES(@company,@account,@opportunity,@user,N'Product B',200);
IF (SELECT COUNT(*) FROM dbo.crm_contract WHERE opportunity_id=@opportunity)<>2 THROW 51001, 'Multiple contracts failed.',1;
INSERT dbo.crm_collection_plan(contract_id,installment_no,collection_method,amount,planned_date) VALUES(@contract,1,N'Bank',100,'2026-12-01');
DECLARE @plan bigint=SCOPE_IDENTITY(),@publicId uniqueidentifier=(SELECT public_id FROM dbo.crm_collection_plan WHERE collection_plan_id=SCOPE_IDENTITY());
CREATE TABLE dbo.codex_plan_reference_test(id int NOT NULL PRIMARY KEY,plan_id bigint NOT NULL REFERENCES dbo.crm_collection_plan(collection_plan_id));
INSERT dbo.codex_plan_reference_test(id,plan_id) VALUES(1,@plan);
UPDATE dbo.crm_collection_plan SET collection_method=N'Cash',amount=100,planned_date='2026-12-02' WHERE contract_id=@contract AND collection_plan_id=@plan AND locked_yn=0;
IF NOT EXISTS(SELECT 1 FROM dbo.crm_collection_plan WHERE collection_plan_id=@plan AND public_id=@publicId AND collection_method=N'Cash') THROW 51002, 'Plan identity was not retained.',1;
UPDATE dbo.crm_collection_plan SET deleted_yn=1,is_current=0,deleted_at=SYSUTCDATETIME(),deleted_by=@user WHERE collection_plan_id=@plan;
IF NOT EXISTS(SELECT 1 FROM dbo.codex_plan_reference_test r JOIN dbo.crm_collection_plan p ON p.collection_plan_id=r.plan_id WHERE p.deleted_yn=1) THROW 51003, 'Plan reference was not retained.',1;
UPDATE dbo.crm_collection_plan SET deleted_yn=0,is_current=1,deleted_at=NULL,deleted_by=NULL WHERE collection_plan_id=@plan;
IF NOT EXISTS(SELECT 1 FROM dbo.codex_plan_reference_test r JOIN dbo.crm_collection_plan p ON p.collection_plan_id=r.plan_id WHERE p.public_id=@publicId AND p.deleted_yn=0) THROW 51004, 'Plan restore failed.',1;
ROLLBACK;
PRINT 'Isolated SQL schema preservation checks passed; test data rolled back.';
